{
  "/workspace/run-ceobench/observe.py": {
    "type": "add",
    "content": "import json
import novamind_api as nm


def query(sql):
    return nm.query(sql)["rows"]


def show(label, rows):
    print(json.dumps({"label": label, "rows": rows}), flush=True)


day = nm.vars.current_day
window_start = day - 7
print(json.dumps({"label": "day", "day": day}), flush=True)
show("cash", query("SELECT COALESCE(SUM(amount), 0) AS cash FROM ledger"))
show(
    "ledger_week",
    query(
        f"SELECT category, SUM(amount) AS amount FROM ledger WHERE day > {window_start} GROUP BY category ORDER BY category"
    ),
)
show(
    "config",
    query("SELECT * FROM config_history ORDER BY day DESC LIMIT 1"),
)
show(
    "overrides",
    query(
        "SELECT setting_type, settings_json FROM config_overrides WHERE id IN (SELECT MAX(id) FROM config_overrides GROUP BY setting_type)"
    ),
)
show(
    "active_book",
    query(
        "SELECT c.group_id, s.plan, COUNT(*) AS customers, SUM(s.seat_count) AS seats, SUM(s.effective_price * s.seat_count) AS monthly_revenue FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status = 'subscribed' AND s.end_day IS NULL GROUP BY c.group_id, s.plan ORDER BY c.group_id, s.plan"
    ),
)
show(
    "week_subscriptions",
    query(
        f"SELECT c.group_id, s.status, s.plan, c.acquisition_source, COUNT(*) AS customers, SUM(s.seat_count) AS seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.start_day > {window_start} GROUP BY c.group_id, s.status, s.plan, c.acquisition_source ORDER BY c.group_id, s.status, s.plan"
    ),
)
show(
    "week_ad_leads",
    query(
        f"SELECT channel_id, group_id, SUM(spend) AS spend, SUM(leads_generated) AS leads, 1000.0 * SUM(leads_generated) / NULLIF(SUM(spend), 0) AS leads_per_1000 FROM ad_channel_leads WHERE day > {window_start} GROUP BY channel_id, group_id ORDER BY channel_id, group_id"
    ),
)
show(
    "service",
    query(
        f"SELECT day, total_usage_units, p95_ms, error_rate, downtime_minutes, capacity_tier, capacity_units FROM service_day WHERE day > {window_start} ORDER BY day"
    ),
)
show(
    "open_issues",
    query(
        "SELECT group_id, COUNT(*) AS open_issues, MAX(days_open) AS max_days_open FROM issues WHERE status = 'open' GROUP BY group_id ORDER BY open_issues DESC"
    ),
)
show(
    "resolved_issues",
    query(
        f"SELECT group_id, COUNT(*) AS resolved, AVG(days_open) AS avg_days_open FROM issues WHERE status = 'resolved' AND resolved_day > {window_start} GROUP BY group_id ORDER BY resolved DESC"
    ),
)
show(
    "open_enterprise_threads",
    query(
        "SELECT e.message_id, e.thread_id, e.customer_id, c.group_id, e.thread_type, e.turn_number, e.sender, e.day, e.seat_count, e.message_text, e.offer_json, s.status, s.plan, s.listed_price, s.effective_price FROM enterprise_turns e JOIN (SELECT thread_id, MAX(message_id) AS max_id FROM enterprise_turns WHERE closed = 0 GROUP BY thread_id) latest ON e.message_id = latest.max_id LEFT JOIN customers c ON c.customer_id = e.customer_id LEFT JOIN subscriptions s ON s.customer_id = e.customer_id AND s.status = 'subscribed' AND s.end_day IS NULL ORDER BY e.day DESC, e.message_id DESC LIMIT 100"
    ),
)
show(
    "research",
    query(
        "SELECT tier, status, COUNT(*) AS projects, SUM(quality_boost_applied) AS applied_boost FROM research_projects GROUP BY tier, status ORDER BY tier, status"
    ),
)
show(
    "notifications",
    query(
        f"SELECT day, type, message FROM notifications WHERE day > {window_start} ORDER BY day DESC, notification_id DESC LIMIT 25"
    ),
)
show(
    "groups",
    query("SELECT group_id, info_level, discovered_day, last_research_day FROM group_info_levels ORDER BY group_id"),
)
show("social", nm.analytics.get_social_posts(days=7, limit=20))
show("market", nm.market.get_market_overview())
"
  }
}

